python -c "
import numpy as np
L=open('opt1.xyz').read().split('\n')
n=int(L[0]); els=[];P=[]
for l in L[2:2+n]:
    p=l.split(); els.append(p[0]); P.append([float(x) for x in p[1:4]])
P=np.array(P)
for i in range(n):
    if els[i]!='Ni': continue
    for j in range(n):
        if i!=j:
            d=np.linalg.norm(P[i]-P[j])
            if d<2.6: print(els[j],j,round(d,3))
"
